function main(): void {
  const ia = new Int32Array(new SharedArrayBuffer(8));
  const r1: any = Atomics.waitAsync(ia, 0, 1);
  console.log(r1.async, r1.value, Object.keys(r1).join(','));
  const r2: any = Atomics.waitAsync(ia, 0, 0, 0);
  console.log(r2.async, r2.value);
  const r3: any = Atomics.waitAsync(ia, 0, 0, -5);
  console.log(r3.async, r3.value);
  console.log(Atomics.waitAsync.length, Atomics.waitAsync.name);
  try { Atomics.waitAsync(new Int32Array(4), 0, 0, 0); } catch (e: any) { console.log('nonshared', e.constructor.name); }
  try { Atomics.waitAsync(new Int16Array(new SharedArrayBuffer(8)), 0, 0, 0); } catch (e: any) { console.log('int16', e.constructor.name); }
  try { Atomics.waitAsync(ia, 2, 0, 0); } catch (e: any) { console.log('range', e.constructor.name); }
  const p: any = Atomics.waitAsync(ia, 0, 0, 10);
  console.log(p.async, typeof p.value.then);
}
